"""Subtasks of cup pyramid."""
from itertools import combinations

from core.grade_episode import Subtask

BASES = {"cup_slot_c": {"pred": "all", "of": [{"pred": "axis_dot", "obj": "cup_slot_c", "min_dot": 0.7, "world_axis": [0, 0, -1]}, {"pred": "all", "of": [{"pred": "lift_above", "obj": "cup_slot_c", "z_above": 0.77921}, {"pred": "z_below", "obj": "cup_slot_c", "z_below": 0.8792099999999999}]}, {"pred": "touching_part", "a": "cup_slot_c", "b": "play_table"}, {"pred": "robot_clear", "bodies": ["cup_slot_c"]}]}, "cup_slot_e": {"pred": "all", "of": [{"pred": "axis_dot", "obj": "cup_slot_e", "min_dot": 0.7, "world_axis": [0, 0, -1]}, {"pred": "all", "of": [{"pred": "lift_above", "obj": "cup_slot_e", "z_above": 0.77921}, {"pred": "z_below", "obj": "cup_slot_e", "z_below": 0.8792099999999999}]}, {"pred": "touching_part", "a": "cup_slot_e", "b": "play_table"}, {"pred": "robot_clear", "bodies": ["cup_slot_e"]}]}, "cup_slot_b": {"pred": "all", "of": [{"pred": "axis_dot", "obj": "cup_slot_b", "min_dot": 0.7, "world_axis": [0, 0, -1]}, {"pred": "all", "of": [{"pred": "lift_above", "obj": "cup_slot_b", "z_above": 0.77921}, {"pred": "z_below", "obj": "cup_slot_b", "z_below": 0.8792099999999999}]}, {"pred": "touching_part", "a": "cup_slot_b", "b": "play_table"}, {"pred": "robot_clear", "bodies": ["cup_slot_b"]}]}}
TOP = {"pred": "all", "of": [{"pred": "any", "of": [{"pred": "all", "of": [{"pred": "axis_dot", "obj": "cup_slot_b", "min_dot": 0.7, "world_axis": [0, 0, -1]}, {"pred": "axis_dot", "obj": "cup_slot_c", "min_dot": 0.7, "world_axis": [0, 0, -1]}, {"pred": "axis_dot", "obj": "cup_slot_e", "min_dot": 0.7, "world_axis": [0, 0, -1]}, {"pred": "all", "of": [{"pred": "lift_above", "obj": "cup_slot_c", "z_above": 0.77921}, {"pred": "z_below", "obj": "cup_slot_c", "z_below": 0.8792099999999999}]}, {"pred": "all", "of": [{"pred": "lift_above", "obj": "cup_slot_e", "z_above": 0.77921}, {"pred": "z_below", "obj": "cup_slot_e", "z_below": 0.8792099999999999}]}, {"pred": "touching_part", "a": "cup_slot_c", "b": "play_table"}, {"pred": "touching_part", "a": "cup_slot_e", "b": "play_table"}, {"pred": "all", "of": [{"pred": "lift_above", "obj": "cup_slot_b", "z_above": 0.8792099999999999}, {"pred": "z_below", "obj": "cup_slot_b", "z_below": 0.9992099999999999}]}, {"pred": "within_dist", "a": "cup_slot_b", "b": "cup_slot_c", "tol": 0.06, "axes": "xy"}, {"pred": "within_dist", "a": "cup_slot_b", "b": "cup_slot_e", "tol": 0.06, "axes": "xy"}, {"pred": "touching_part", "a": "cup_slot_b", "b": "cup_slot_c"}, {"pred": "touching_part", "a": "cup_slot_b", "b": "cup_slot_e"}]}, {"pred": "all", "of": [{"pred": "axis_dot", "obj": "cup_slot_b", "min_dot": 0.7, "world_axis": [0, 0, -1]}, {"pred": "axis_dot", "obj": "cup_slot_c", "min_dot": 0.7, "world_axis": [0, 0, -1]}, {"pred": "axis_dot", "obj": "cup_slot_e", "min_dot": 0.7, "world_axis": [0, 0, -1]}, {"pred": "all", "of": [{"pred": "lift_above", "obj": "cup_slot_b", "z_above": 0.77921}, {"pred": "z_below", "obj": "cup_slot_b", "z_below": 0.8792099999999999}]}, {"pred": "all", "of": [{"pred": "lift_above", "obj": "cup_slot_e", "z_above": 0.77921}, {"pred": "z_below", "obj": "cup_slot_e", "z_below": 0.8792099999999999}]}, {"pred": "touching_part", "a": "cup_slot_b", "b": "play_table"}, {"pred": "touching_part", "a": "cup_slot_e", "b": "play_table"}, {"pred": "all", "of": [{"pred": "lift_above", "obj": "cup_slot_c", "z_above": 0.8792099999999999}, {"pred": "z_below", "obj": "cup_slot_c", "z_below": 0.9992099999999999}]}, {"pred": "within_dist", "a": "cup_slot_c", "b": "cup_slot_b", "tol": 0.06, "axes": "xy"}, {"pred": "within_dist", "a": "cup_slot_c", "b": "cup_slot_e", "tol": 0.06, "axes": "xy"}, {"pred": "touching_part", "a": "cup_slot_c", "b": "cup_slot_b"}, {"pred": "touching_part", "a": "cup_slot_c", "b": "cup_slot_e"}]}, {"pred": "all", "of": [{"pred": "axis_dot", "obj": "cup_slot_b", "min_dot": 0.7, "world_axis": [0, 0, -1]}, {"pred": "axis_dot", "obj": "cup_slot_c", "min_dot": 0.7, "world_axis": [0, 0, -1]}, {"pred": "axis_dot", "obj": "cup_slot_e", "min_dot": 0.7, "world_axis": [0, 0, -1]}, {"pred": "all", "of": [{"pred": "lift_above", "obj": "cup_slot_b", "z_above": 0.77921}, {"pred": "z_below", "obj": "cup_slot_b", "z_below": 0.8792099999999999}]}, {"pred": "all", "of": [{"pred": "lift_above", "obj": "cup_slot_c", "z_above": 0.77921}, {"pred": "z_below", "obj": "cup_slot_c", "z_below": 0.8792099999999999}]}, {"pred": "touching_part", "a": "cup_slot_b", "b": "play_table"}, {"pred": "touching_part", "a": "cup_slot_c", "b": "play_table"}, {"pred": "all", "of": [{"pred": "lift_above", "obj": "cup_slot_e", "z_above": 0.8792099999999999}, {"pred": "z_below", "obj": "cup_slot_e", "z_below": 0.9992099999999999}]}, {"pred": "within_dist", "a": "cup_slot_e", "b": "cup_slot_b", "tol": 0.06, "axes": "xy"}, {"pred": "within_dist", "a": "cup_slot_e", "b": "cup_slot_c", "tol": 0.06, "axes": "xy"}, {"pred": "touching_part", "a": "cup_slot_e", "b": "cup_slot_b"}, {"pred": "touching_part", "a": "cup_slot_e", "b": "cup_slot_c"}]}]}, {"pred": "robot_clear", "bodies": ["cup_slot_b", "cup_slot_c", "cup_slot_e"]}]}
PAIR_MAX_XY_M = 0.12


def bases(s):
    return {body for body, spec in BASES.items() if s.tree(spec)}


def close_pair(s, valid):
    return any(a in valid and b in valid and s.within_dist(a=a, b=b, axes="xy", tol=PAIR_MAX_XY_M) for a, b in combinations(BASES, 2))


def subtasks():
    return [
        Subtask('pick a cup and place it upside down on the table', lambda s: bool(bases(s)) or s.tree(TOP)),
        Subtask('pick a cup and place it upside down next to the previous cup', lambda s: close_pair(s, bases(s)) or s.tree(TOP)),
        Subtask('pick a cup and place it upside down on top of the two, touching both', lambda s: s.success()),
    ]
